={
  "model": "meta/llama-3.3-70b-instruct",
  "messages": [
    {
      "role": "system",
      "content": "You are an AI qualification assistant for Salesforce release pain points. Return ONLY valid JSON. No markdown. The JSON must have exactly these keys: route_to_human (boolean), urgency (one of: urgent, high, medium, low), pain_point (string), summary (string), recommended_action (string), confidence (number 0-1). Set route_to_human to true if the message describes a production outage, failed deployment, data loss, security issue, release blocker, or the person explicitly asks for immediate human help. Otherwise set route_to_human to false."
    },
    {
      "role": "user",
      "content": {{ JSON.stringify($json.body || $json) }}
    }
  ],
  "temperature": 0.1,
  "top_p": 0.7,
  "max_tokens": 1024,
  "stream": false
}

parameters.jsCode:
const webhook = $('Webhook').item.json.body || $('Webhook').item.json;

const ai = $json;
const raw =
  ai.choices?.[0]?.message?.content ??
  ai.content?.[0]?.text ??
  ai.output ??
  '';

let cleaned = String(raw).trim();

cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/, '')
  .replace(/```$/, '')
  .trim();

const first = cleaned.indexOf('{');
const last = cleaned.lastIndexOf('}');
if (first !== -1 && last !== -1 && last > first) {
  cleaned = cleaned.slice(first, last + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    route_to_human: false,
    urgency: 'low',
    pain_point: 'parse_error',
    summary: 'Could not parse AI response',
    recommended_action: 'Review manually',
    confidence: 0
  };
}

if (typeof parsed.route_to_human === 'string') {
  parsed.route_to_human = parsed.route_to_human.toLowerCase() === 'true';
}

if (typeof parsed.confidence !== 'number') {
  parsed.confidence = Number(parsed.confidence) || 0;
}

return [{
  json: {
    ...webhook,
    ...parsed,
    _raw_ai_response: raw
  }
}];
